+// The audit log: one entry per request that changes data, never edited.
+
+/** Appends an entry (time, key name, method, path, status). */
+export function recordAudit(store, entry) {
+  (store.data.audit ??= []).push(entry);
+}
+
+/** All entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
