@@ -0,0 +1,32 @@
+// API keys and roles. Roles are ordered: viewer < cook < manager.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+// Writes a cook may do; every other write needs a manager.
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The role needed to call `method` on `path`. */
+export function requiredRole(method, path) {
+  if (method === "GET") return path === "/audit" ? "manager" : "viewer";
+  return COOK_WRITES.some(([m, re]) => m === method && re.test(path)) ? "cook" : "manager";
+}
+
+/** The API key entry for an `Authorization: Bearer <key>` header, or null. */
+export function findKey(store, header) {
+  const m = /^Bearer (.+)$/.exec(String(header ?? ""));
+  return (m && (store.data.apiKeys ?? []).find((k) => k.key === m[1])) || null;
+}
+
+/** Throws unauthorized (no or unknown key) or forbidden (role too low); returns the key entry. */
+export function authorize(store, header, method, path) {
+  const entry = findKey(store, header);
+  if (!entry) throw new AppError("unauthorized");
+  if ((RANK[entry.role] ?? 0) < RANK[requiredRole(method, path)]) throw new AppError("forbidden");
+  return entry;
+}
